# Which secrets each fleet command needs - generated by
# scripts/settings-manifest, do not edit. The cti-agent wrapper reads it to
# give a hand run the same ImportCredential= grants its timer has.
# program SECRET...  (a program with none is not listed)
cti-agent ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN CLIENT_ID CLIENT_SECRET FALCON_BASE_URL FALCON_CLIENT_ID FALCON_CLIENT_SECRET JIRA_API_TOKEN JIRA_BASE_URL JIRA_CLOUD_ID JIRA_EMAIL QUALYS_BASE_URL QUALYS_PASSWORD QUALYS_USERNAME REPORT_REDACTION_SALT TENANT_ID
cti-alert CLIENT_ID CLIENT_SECRET TENANT_ID
cti-appreport CLIENT_ID CLIENT_SECRET JIRA_API_TOKEN JIRA_BASE_URL JIRA_CLOUD_ID JIRA_EMAIL QUALYS_BASE_URL QUALYS_PASSWORD QUALYS_USERNAME TENANT_ID
cti-appscan CLIENT_ID CLIENT_SECRET JIRA_API_TOKEN JIRA_BASE_URL JIRA_CLOUD_ID JIRA_EMAIL QUALYS_BASE_URL QUALYS_PASSWORD QUALYS_USERNAME TENANT_ID
cti-budget CLAUDE_CODE_OAUTH_TOKEN
cti-domains GODADDY_PAT POD_API_TOKEN POD_CLUSTER_ID
cti-enrich NVD_API_KEY
cti-falcon FALCON_BASE_URL FALCON_CLIENT_ID FALCON_CLIENT_SECRET
cti-jira CLIENT_ID CLIENT_SECRET JIRA_API_TOKEN JIRA_BASE_URL JIRA_CLOUD_ID JIRA_EMAIL QUALYS_BASE_URL QUALYS_PASSWORD QUALYS_USERNAME TENANT_ID
cti-mailbox CLIENT_ID CLIENT_SECRET JIRA_API_TOKEN JIRA_BASE_URL JIRA_CLOUD_ID JIRA_EMAIL QUALYS_BASE_URL QUALYS_PASSWORD QUALYS_USERNAME TENANT_ID
cti-mailer CLAUDE_CODE_OAUTH_TOKEN CLIENT_ID CLIENT_SECRET NVD_API_KEY QUALYS_BASE_URL TENANT_ID
cti-patchtuesday CLIENT_ID CLIENT_SECRET JIRA_API_TOKEN JIRA_BASE_URL JIRA_CLOUD_ID JIRA_EMAIL QUALYS_BASE_URL QUALYS_PASSWORD QUALYS_USERNAME TENANT_ID
cti-podprobe POD_API_TOKEN POD_CLUSTER_ID
cti-supplier CLIENT_ID CLIENT_SECRET JIRA_API_TOKEN JIRA_BASE_URL JIRA_CLOUD_ID JIRA_EMAIL QUALYS_BASE_URL QUALYS_PASSWORD QUALYS_USERNAME TENANT_ID
cti-triage ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN FALCON_BASE_URL FALCON_CLIENT_ID FALCON_CLIENT_SECRET
cti-vmscan CLIENT_ID CLIENT_SECRET JIRA_API_TOKEN JIRA_BASE_URL JIRA_CLOUD_ID JIRA_EMAIL QUALYS_BASE_URL QUALYS_PASSWORD QUALYS_USERNAME TENANT_ID
fleet-config ANTHROPIC_API_KEY ANTHROPIC_AUTH_TOKEN CLAUDE_CODE_OAUTH_TOKEN CLIENT_ID CLIENT_SECRET FALCON_BASE_URL FALCON_CLIENT_ID FALCON_CLIENT_SECRET JIRA_API_TOKEN JIRA_BASE_URL JIRA_CLOUD_ID JIRA_EMAIL QUALYS_BASE_URL QUALYS_PASSWORD QUALYS_USERNAME REPORT_REDACTION_SALT TENANT_ID
